): ?><img src="<?= base_url($oldPath) ?>" class="comparison-photo rounded border" alt="Foto lama"><?php else: ?><div class="small text-muted border rounded p-3 text-center">Tidak ada</div><?php endif; ?></div><div class="col-6"><div class="small text-primary mb-1">Baru</div><?php if($newPath): ?><img src="<?= base_url($newPath) ?>" class="comparison-photo rounded border border-primary" alt="Foto baru"><?php else: ?><div class="small text-muted border rounded p-3 text-center">Tidak ada</div><?php endif; ?></div></div></div><?php endforeach; ?></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Tutup</button></div></div></div></div>
