<script>(()=>{const search=document.getElementById('changeSearch'),status=document.getElementById('changeStatus'),count=document.getElementById('changeCount'),rows=[...document.querySelectorAll('#changeTable tbody tr')],empty=document.getElementById('emptyState'),size=10,pager=document.createElement('div');pager.className='pagination-bar bg-white px-3 py-2 d-flex justify-content-end';document.querySelector('#changeTable').parentElement.parentElement.appendChild(pager);let page=1;const render=()=>{const q=search.value.toLowerCase().trim(),s=status.value,filtered=rows.filter(r=>(!q||r.dataset.search.includes(q))&&(!s||r.dataset.status===s)),pages=Math.max(1,Math.ceil(filtered.length/size));page=Math.min(page,pages);rows.forEach(r=>r.classList.add('d-none'));filtered.slice((page-1)*size,page*size).forEach(r=>r.classList.remove('d-none'));count.textContent=filtered.length+' pengajuan';pager.innerHTML='';for(let i=1;i<=pages;i++){const b=document.createElement('button');b.type='button';b.className='btn btn-sm '+(i===page?'btn-primary':'btn-outline-secondary')+' ms-1';b.textContent=i;b.onclick=()=>{page=i;render()};pager.appendChild(b)}empty.classList.toggle('d-none',filtered.length>0)};search.oninput=()=>{page=1;render()};status.onchange=()=>{page=1;render()};render();document.querySelectorAll('[data-photo]').forEach(btn=>btn.onclick=()=>{document.getElementById('previewFotoImage').src=btn.dataset.photo;document.getElementById('previewFotoTitle').textContent='Preview '+btn.dataset.label});document.querySelectorAll('form[action*="anggota-perubahan/approve"],form[action*="anggota-perubahan/reject"]').forEach(f=>f.onsubmit=e=>{const ok=f.action.includes('/approve/');if(!confirm(ok?'Setujui perubahan profil anggota ini? Data baru akan diterapkan.':'Tolak perubahan profil anggota ini? Pastikan alasan penolakan sudah diisi.'))e.preventDefault()})})()</script>
<script>
document.querySelectorAll('.doc-link[data-photo]').forEach(button=>{const thumb=document.createElement('img'),source=button.dataset.photo;thumb.className='doc-thumb';thumb.src=source+(source.includes('?')?'&':'?')+'v='+Date.now();thumb.alt=button.dataset.label||'Thumbnail dokumen';thumb.loading='lazy';button.prepend(thumb)});
document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{
  const image=document.getElementById('previewFotoImage'), controls=document.getElementById('photoRotateControls');
  let turns=0;
  const source=button.dataset.photo;
  image.style.display='block';
  image.onerror=()=>{image.style.display='none';};
  image.src=button.querySelector('.doc-thumb')?.src||source;
  image.style.transform='rotate(0deg)';
  const fitImage=()=>{
    if(!image.naturalWidth || !image.naturalHeight) return;
    const stage=image.parentElement, width=stage.clientWidth, height=stage.clientHeight;
    if(width<=0 || height<=0) return;
    const rotated=turns%2===1, imageWidth=rotated?image.naturalHeight:image.naturalWidth, imageHeight=rotated?image.naturalWidth:image.naturalHeight;
    const scale=Math.min(width/imageWidth,height/imageHeight);
    image.style.maxWidth='none';
    image.style.maxHeight='none';
    image.style.width=(image.naturalWidth*scale)+'px';
    image.style.height=(image.naturalHeight*scale)+'px';
  };
  image.onload=fitImage;
  setTimeout(fitImage,400);
  controls.innerHTML='<button type="button" id="rotatePhotoPreviewBtn" class="btn btn-outline-warning btn-sm">↻ Putar Preview</button><button type="button" id="savePhotoRotationBtn" class="btn btn-warning btn-sm">Simpan Rotasi</button>';
  document.getElementById('rotatePhotoPreviewBtn').onclick=()=>{turns=(turns+1)%4;image.style.transform=`rotate(${turns*90}deg)`;fitImage()};
  document.getElementById('savePhotoRotationBtn').onclick=()=>{const form=document.createElement('form'),input=document.createElement('input');form.method='post';form.action='<?= base_url('admin/anggota-perubahan/rotate-file') ?>/'+encodeURIComponent(button.dataset.photo.split('/').pop());input.type='hidden';input.name='turns';input.value=turns;form.appendChild(input);document.body.appendChild(form);form.submit()};
}));
</script>
<script>
document.querySelectorAll('.modal[id^="detailPerubahan"]').forEach(modal=>{
  modal.addEventListener('show.bs.modal',()=>{
    if(modal.dataset.aligned==='1') return;
    const cols=modal.querySelectorAll('.modal-body > .row:first-child > .col-md-6');
    if(cols.length<2) return;
    const allowed={anggota_id:'Anggota ID',anggota_newnoreg:'Anggota New Noreg',anggota_nama:'Nama',anggota_noktp:'No. KTP',anggota_alamat:'Alamat',anggota_tgllhr:'Tanggal Lahir',anggota_tmplhr:'Tempat Lahir',anggota_jnsklm:'Jenis Kelamin',anggota_peker:'Pekerjaan',anggota_pente:'Pendidikan Terakhir',anggota_nohp:'No. HP',anggota_klrhnid:'Kelurahan',anggota_staagamaid:'Agama',nomor_kk:'Nomor KK',provinsi:'Provinsi',kabupaten_kota:'Kota/Kabupaten',kecamatan_nama:'Kecamatan',kelurahan_nama:'Kelurahan'};
    const maps=[new Map(),new Map()];
    cols.forEach((col,side)=>col.querySelectorAll('.data-item').forEach(item=>{
      const rawKey=item.querySelector('.data-key')?.textContent.trim()||'';
      const keyName=rawKey.toLowerCase().replace(/ /g,'_');
      if(!allowed[keyName]) return;
      const key=allowed[keyName];
      const value=item.cloneNode(true); value.querySelector('.data-key')?.remove();
      let display=value.textContent.trim()||'-';
      const wilayah=<?= json_encode($wilayahMap??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,agama=<?= json_encode($agamaMap??[],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
      if(keyName==='anggota_klrhnid' && wilayah[display]) display=[wilayah[display].kelurahan_nama,wilayah[display].kecamatan_nama,wilayah[display].kabupaten_kota,wilayah[display].provinsi].filter(Boolean).join(', ');
      if(keyName==='anggota_staagamaid' && agama[display]) display=agama[display];
      maps[side].set(key,display);
    }));
    const keys=Object.values(allowed).filter(key=>maps[0].has(key)||maps[1].has(key));
    const wrap=document.createElement('div');
    wrap.className='table-responsive';
    wrap.innerHTML='<table class="table table-sm table-bordered align-middle mb-0 compare-table"><thead class="table-light"><tr><th style="width:28%">Field</th><th>Data lama</th><th>Data baru</th></tr></thead><tbody></tbody></table>';
    const body=wrap.querySelector('tbody');
    keys.forEach(key=>{const tr=document.createElement('tr'),th=document.createElement('th'),oldTd=document.createElement('td'),newTd=document.createElement('td');th.className='small text-muted';th.textContent=key;oldTd.textContent=maps[0].get(key)||'-';newTd.textContent=maps[1].get(key)||'-';newTd.className='bg-primary-subtle';tr.append(th,oldTd,newTd);body.appendChild(tr)});
    cols[0].parentElement.replaceWith(wrap);
    modal.dataset.aligned='1';
  });
});
</script>
<style>.modal[id^="detailPerubahan"] .modal-body>.row:first-child{visibility:hidden}.photo-preview-stage{height:70vh;max-height:600px;display:flex;align-items:center;justify-content:center;overflow:hidden}.photo-preview-stage img{max-width:100%;max-height:100%;object-fit:contain;transition:transform .2s ease}</style>
